        Result.fromValue(stopBlocking())

    suspend fun stopAsync(): Result = suspendCancellableCoroutine { continuation ->
        val callback = StopCallback { result ->
            val r = Result.fromValue(result)
            if (r == Result.SUCCESS) {
                continuation.resume(r)
            } else {
